        { en: "🥁 Round 1.", fr: "🥁 Manche 1.", es: "🥁 Ronda 1.", de: "🥁 Runde 1.", it: "🥁 Round 1.", da: "🥁 Runde 1.", bg: "🥁 Рунд 1.", tr: "🥁 Tur 1." },
        { image: "assets/ecosse.png", alt: { en: "A rugged coastal cliff overlooking grey water and distant mountains under overcast skies, with green grass on top of the cliffs.", fr: "Une falaise côtière escarpée surplombant des eaux grises et des montagnes lointaines sous un ciel couvert, avec de l'herbe verte au sommet des falaises.", es: "Un acantilado costero escarpado sobre aguas grises y montañas lejanas bajo un cielo nublado, con hierba verde encima de los acantilados.", de: "Eine schroffe Küstenklippe über grauem Wasser und fernen Bergen unter bewölktem Himmel, mit grünem Gras auf den Klippen.", it: "Una scogliera costiera frastagliata sopra acque grigie e montagne lontane sotto un cielo coperto, con erba verde sopra le scogliere.", da: "En forrevet kystklippe over gråt vand og fjerne bjerge under en overskyet himmel, med grønt græs på toppen af klipperne.", bg: "Стръмна крайбрежна скала над сиви води и далечни планини под облачно небе, със зелена трева на върха.", tr: "Bulutlu gökyüzünün altında, gri sulara ve uzaktaki dağlara bakan engebeli bir kıyı uçurumu; uçurumların üzerinde yeşil çimenler var." } },
        { en: "A Scottish coastline. Real photograph or AI-generated?", fr: "Une côte écossaise. Vraie photo ou image générée par IA ?", es: "Una costa escocesa. ¿Foto real o imagen generada por IA?", de: "Eine schottische Küste. Echtes Foto oder KI-generiert?", it: "Una costa scozzese. Foto vera o immagine generata dall'IA?", da: "En skotsk kyst. Ægte foto eller AI-genereret?", bg: "Шотландско крайбрежие. Истинска снимка или генерирана от AI?", tr: "Bir İskoç kıyısı. Gerçek fotoğraf mı, AI tarafından mı üretilmiş?" }
